import React, { useContext, useState, useEffect } from 'react';
import { AuthContext } from '../../context/AuthContext';
import { FiBriefcase, FiCheckCircle, FiClock, FiDollarSign, FiArrowRight } from 'react-icons/fi';
import { Link } from 'react-router-dom';
import CreateProfile from '../profile/CreateProfile';
import API from '../../utils/api';

const StudentDashboard = () => {
  const { user } = useContext(AuthContext);
  const [showCreateProfile, setShowCreateProfile] = useState(false);
  const [applications, setApplications] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchApplications();
  }, []);

  const fetchApplications = async () => {
    try {
      const res = await API.get('/application/student');
      setApplications(res.data);
      setLoading(false);
    } catch (err) {
      console.error('Fetch apps error:', err);
      setLoading(false);
    }
  };

  if (showCreateProfile) {
    return <CreateProfile />;
  }

  // Calculate real stats
  const totalApplications = applications.length;
  const pendingCount = applications.filter(a => a.status === 'pending').length;
  const acceptedCount = applications.filter(a => a.status === 'accepted').length;
  const rejectedCount = applications.filter(a => a.status === 'rejected').length;

  return (
    <div className="min-h-screen bg-gray-50 py-12">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">

        {/* Header */}
        <div className="mb-8">
          <h1 className="text-4xl font-bold text-gray-800">Welcome back, {user?.name}! 👋</h1>
          <p className="text-gray-600 mt-2">Here's what's happening with your projects</p>
        </div>

        {/* Stats Cards */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-8">
          <div className="bg-white rounded-lg shadow-md p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-gray-500 text-sm">Total Applied</p>
                <p className="text-3xl font-bold text-gray-800 mt-1">{totalApplications}</p>
              </div>
              <div className="w-12 h-12 bg-primary bg-opacity-10 rounded-full flex items-center justify-center">
                <FiBriefcase className="text-primary text-2xl" />
              </div>
            </div>
          </div>

          <div className="bg-white rounded-lg shadow-md p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-gray-500 text-sm">Accepted</p>
                <p className="text-3xl font-bold text-gray-800 mt-1">{acceptedCount}</p>
              </div>
              <div className="w-12 h-12 bg-green-100 rounded-full flex items-center justify-center">
                <FiCheckCircle className="text-green-500 text-2xl" />
              </div>
            </div>
          </div>

          <div className="bg-white rounded-lg shadow-md p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-gray-500 text-sm">Pending</p>
                <p className="text-3xl font-bold text-gray-800 mt-1">{pendingCount}</p>
              </div>
              <div className="w-12 h-12 bg-yellow-100 rounded-full flex items-center justify-center">
                <FiClock className="text-yellow-500 text-2xl" />
              </div>
            </div>
          </div>

          <div className="bg-white rounded-lg shadow-md p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-gray-500 text-sm">Rejected</p>
                <p className="text-3xl font-bold text-gray-800 mt-1">{rejectedCount}</p>
              </div>
              <div className="w-12 h-12 bg-red-100 rounded-full flex items-center justify-center">
                <FiDollarSign className="text-red-400 text-2xl" />
              </div>
            </div>
          </div>
        </div>

        {/* Two Column Grid */}
        <div className="grid md:grid-cols-3 gap-8">

          {/* My Applications - Left (wider) */}
          <div className="md:col-span-2 bg-white rounded-lg shadow-md p-6">
            <div className="flex justify-between items-center mb-6">
              <h2 className="text-2xl font-bold text-gray-800">My Applications</h2>
              <Link to="/browse" className="text-primary hover:underline text-sm font-medium flex items-center">
                Browse More <FiArrowRight className="ml-1" />
              </Link>
            </div>

            {loading ? (
              <div className="flex justify-center py-8">
                <div className="animate-spin rounded-full h-8 w-8 border-t-4 border-primary"></div>
              </div>
            ) : applications.length === 0 ? (
              <div className="text-center py-10">
                <p className="text-gray-500">No applications yet.</p>
                <Link to="/browse" className="mt-3 inline-block px-6 py-2 bg-primary text-white rounded-lg hover:bg-secondary transition font-semibold">
                  Browse Projects
                </Link>
              </div>
            ) : (
              <div className="space-y-4">
                {applications.map((app) => (
                  <div key={app._id} className="border border-gray-200 rounded-lg p-4 hover:border-primary transition">
                    <div className="flex justify-between items-start">
                      <div className="flex-1">
                        <h3 className="font-bold text-gray-800">{app.project?.title}</h3>
                        <p className="text-sm text-gray-600 mt-1">{app.project?.description}</p>
                        <div className="flex flex-wrap gap-2 mt-2">
                          {app.project?.requiredSkills?.map((skill, i) => (
                            <span key={i} className="px-2 py-1 bg-gray-100 text-gray-600 rounded-full text-xs">{skill}</span>
                          ))}
                        </div>
                        <div className="flex items-center gap-4 mt-3 text-sm text-gray-500">
                          <span><FiDollarSign className="inline" /> Budget: ${app.project?.budget}</span>
                          <span><FiClock className="inline" /> {app.project?.duration}</span>
                        </div>
                      </div>

                      {/* Status Badge */}
                      <span className={`px-3 py-1 rounded-full text-sm font-semibold whitespace-nowrap ml-4 ${
                        app.status === 'pending' ? 'bg-yellow-100 text-yellow-700' :
                        app.status === 'accepted' ? 'bg-green-100 text-green-700' :
                        'bg-red-100 text-red-700'
                      }`}>
                        {app.status.charAt(0).toUpperCase() + app.status.slice(1)}
                      </span>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>

          {/* Right sidebar */}
          <div className="space-y-6">
            {/* Profile Card */}
            <div className="bg-white rounded-lg shadow-md p-6">
              <h2 className="text-xl font-bold text-gray-800 mb-3">Your Profile</h2>
              <p className="text-gray-600 text-sm mb-4">Add your skills to get matched with the best projects.</p>
              <button
                onClick={() => setShowCreateProfile(true)}
                className="w-full px-6 py-3 bg-gray-800 text-white rounded-lg hover:bg-gray-900 transition font-semibold"
              >
                Update Profile
              </button>
            </div>

            {/* Quick Links */}
            <div className="bg-white rounded-lg shadow-md p-6">
              <h2 className="text-xl font-bold text-gray-800 mb-3">Quick Links</h2>
              <div className="space-y-3">
                <Link to="/browse" className="flex items-center justify-between p-3 rounded-lg hover:bg-gray-50 transition">
                  <span className="text-gray-700 font-medium">Browse Projects</span>
                  <FiArrowRight className="text-primary" />
                </Link>
                <button
                  onClick={() => setShowCreateProfile(true)}
                  className="flex items-center justify-between p-3 rounded-lg hover:bg-gray-50 transition w-full text-left"
                >
                  <span className="text-gray-700 font-medium">Edit Profile</span>
                  <FiArrowRight className="text-primary" />
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default StudentDashboard;
